dept_id = #{deptId}, project_id = #{projectId}, task_id = #{taskId}, log_date = #{logDate}, start_time = #{startTime}, end_time = #{endTime}, duration = #{duration}, log_type = #{logType}, log_status = #{logStatus}, billable = #{billable}, content = #{content}, source = #{source}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
