mapper.select:
select w.log_date as statDate,
	sum(w.duration) as totalSeconds,
	sum(case when w.billable = '0' then w.duration else 0 end) as billableSeconds,
	count(1) as recordCount
from biz_work_log w

	w.del_flag = '0' and w.log_status = '1'
	 AND w.user_id = #{userId} 
	 AND w.dept_id = #{deptId} 
	 AND w.project_id = #{projectId} 
	 AND w.task_id = #{taskId} 
	 AND w.log_date >= #{params.beginLogDate} 
	 AND w.log_date <= #{params.endLogDate} 

	${params.dataScope}

group by w.log_date
order by w.log_date desc

select w.project_id as dimId,
	p.project_name as dimName,
	sum(w.duration) as totalSeconds,
	sum(case when w.billable = '0' then w.duration else 0 end) as billableSeconds,
	count(1) as recordCount
from biz_work_log w
	left join biz_project p on p.project_id = w.project_id and p.del_flag = '0'

	w.del_flag = '0' and w.log_status = '1'
	 AND w.user_id = #{userId} 
	 AND w.dept_id = #{deptId} 
	 AND w.project_id = #{projectId} 
	 AND w.task_id = #{taskId} 
	 AND w.log_date >= #{params.beginLogDate} 
	 AND w.log_date <= #{params.endLogDate} 

	${params.dataScope}

group by w.project_id, p.project_name
order by totalSeconds desc

select w.user_id as dimId,
	u.nick_name as dimName,
	sum(w.duration) as totalSeconds,
	sum(case when w.billable = '0' then w.duration else 0 end) as billableSeconds,
	count(1) as recordCount
from biz_work_log w
	left join sys_user u on u.user_id = w.user_id

	w.del_flag = '0' and w.log_status = '1'
	 AND w.user_id = #{userId} 
	 AND w.dept_id = #{deptId} 
	 AND w.project_id = #{projectId} 
	 AND w.task_id = #{taskId} 
	 AND w.log_date >= #{params.beginLogDate} 
	 AND w.log_date <= #{params.endLogDate} 

	${params.dataScope}

group by w.user_id, u.nick_name
order by totalSeconds desc

select sum(w.duration) as totalSeconds,
	sum(case when w.billable = '0' then w.duration else 0 end) as billableSeconds,
	count(1) as recordCount
from biz_work_log w

	w.del_flag = '0' and w.log_status = '1'
	 AND w.user_id = #{userId} 
	 AND w.dept_id = #{deptId} 
	 AND w.project_id = #{projectId} 
	 AND w.task_id = #{taskId} 
	 AND w.log_date >= #{params.beginLogDate} 
	 AND w.log_date <= #{params.endLogDate} 

	${params.dataScope}

select w.task_id as dimId,
	sum(w.duration) as totalSeconds
from biz_work_log w

	w.del_flag = '0' and w.log_status = '1' and w.task_id is not null
	 AND w.user_id = #{userId} 
	 AND w.dept_id = #{deptId} 
	 AND w.project_id = #{projectId} 
	 AND w.task_id = #{taskId} 
	 AND w.log_date >= #{params.beginLogDate} 
	 AND w.log_date <= #{params.endLogDate} 

group by w.task_id
